#include "nvfs_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

static nvfs_check_format_type (void) ;

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void nvfs_init_existing (void)
{
  NVFS_Entry  nvfs_entry  ;
  NVFS_Header nvfs_header ;

  UInt16      curr_entry  ;

  nvfs_check_format_type () ;

  nvfs_rd_header (& nvfs_header) ;

  curr_entry = nvfs_header.mem.list.root ;

  while (curr_entry)
    {
      nvfs_rd_entry (& nvfs_entry , curr_entry) ;

      curr_entry = nvfs_entry.link.next ;
    }
}

//--------------------------------------------------------------------------//

static nvfs_check_format_type (void)
{
  UInt8 format_type ;

  if (!nvram_rd (nvfs_vars.nvram.beg , & format_type , sizeof format_type) || format_type != NVFS_FORMAT_TYPE_1_00)
    {
      NvfsThrow NVFS_ERROR ;
    }
}

